-- SADM-PP-L5-022 isolated cutover 11: WAIVER_AUTHORITY_V1.
-- Materializes the dedicated one-use waiver store and promotes the exact guarded capability.
-- Non-production only. No runtime/deploy/production. No reuse of validation exemptions.

create table if not exists private.lf_post_pase_waivers (
  waiver_id bigint generated by default as identity primary key,
  post_pase_execution_id text not null,
  control_id text not null,
  plan_digest text not null check (plan_digest ~ '^[0-9a-f]{64}$'),
  merge_sha text not null check (merge_sha ~ '^[0-9a-f]{40}$'),
  source_revision text not null check (source_revision ~ '^[0-9a-f]{40}$'),
  subject_ref text not null,
  rationale text not null check (length(btrim(rationale)) >= 20),
  approval_authority text not null check (approval_authority = 'LF_GOVERNANCE'),
  approval_event_id bigint not null references public.lf_eventos(id),
  approval_decision text not null check (approval_decision = 'APPROVED'),
  approved_at timestamptz not null,
  expires_at timestamptz not null,
  max_uses integer not null default 1 check (max_uses = 1),
  uses_count integer not null default 0 check (uses_count between 0 and 1),
  active boolean not null default true,
  consumed_at timestamptz,
  consumed_by_execution_id text,
  consumed_by_request_digest text check (consumed_by_request_digest is null or consumed_by_request_digest ~ '^[0-9a-f]{64}$'),
  grant_sha256 text not null check (grant_sha256 ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint lf_post_pase_waivers_expiry_chk check (expires_at > approved_at and expires_at <= approved_at + interval '1 hour'),
  constraint lf_post_pase_waivers_consumption_chk check (
    (uses_count=0 and consumed_at is null and consumed_by_execution_id is null and consumed_by_request_digest is null)
    or
    (uses_count=1 and consumed_at is not null and consumed_by_execution_id is not null and consumed_by_request_digest is not null and active=false)
  )
);

create unique index if not exists lf_post_pase_waivers_exact_scope_active_uk
on private.lf_post_pase_waivers(post_pase_execution_id,control_id,plan_digest,merge_sha,source_revision,subject_ref)
where active;

create or replace function private.lf_post_pase_waiver_readback_v1(
  p_waiver_id bigint,
  p_post_pase_execution_id text,
  p_control_id text,
  p_plan_digest text,
  p_merge_sha text,
  p_source_revision text,
  p_subject_ref text
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public,extensions
as $fn$
declare r private.lf_post_pase_waivers%rowtype; v_scope jsonb; v_pre jsonb; v_digest text;
begin
  select * into r from private.lf_post_pase_waivers where waiver_id=p_waiver_id;
  if not found then return jsonb_build_object('schema_version','LF_POST_PASE_WAIVER_GRANT_READBACK_V1','authority_layer','WAIVER_AUTHORITY_STORE','decision','WAIVER_GRANT_MISSING','ready',false,'waiver_id',p_waiver_id); end if;
  v_scope:=jsonb_build_object('post_pase_execution_id',p_post_pase_execution_id,'control_id',p_control_id,'plan_digest',p_plan_digest,'merge_sha',p_merge_sha,'source_revision',p_source_revision,'subject_ref',p_subject_ref);
  if (r.post_pase_execution_id,r.control_id,r.plan_digest,r.merge_sha,r.source_revision,r.subject_ref) is distinct from (p_post_pase_execution_id,p_control_id,p_plan_digest,p_merge_sha,p_source_revision,p_subject_ref) then
    return jsonb_build_object('schema_version','LF_POST_PASE_WAIVER_GRANT_READBACK_V1','authority_layer','WAIVER_AUTHORITY_STORE','decision','WAIVER_SCOPE_MISMATCH','ready',false,'waiver_id',p_waiver_id,'scope',v_scope);
  end if;
  v_pre:=jsonb_build_object('schema_version','LF_POST_PASE_WAIVER_GRANT_READBACK_V1','authority_layer','WAIVER_AUTHORITY_STORE','decision',case when r.active and r.uses_count=0 and r.expires_at>clock_timestamp() then 'WAIVER_GRANT_CURRENT' else 'WAIVER_GRANT_NOT_CURRENT' end,'ready',(r.active and r.uses_count=0 and r.expires_at>clock_timestamp()),'waiver_id',r.waiver_id,'scope',v_scope,'approval_authority',r.approval_authority,'approval_decision',r.approval_decision,'approval_event_id',r.approval_event_id,'approved_at',r.approved_at,'expires_at',r.expires_at,'max_uses',r.max_uses,'uses_count',r.uses_count,'active',r.active,'consumed_at',r.consumed_at,'rationale',r.rationale,'grant_sha256',r.grant_sha256);
  v_digest:=encode(extensions.digest(convert_to(v_pre::text,'UTF8'),'sha256'),'hex');
  return v_pre||jsonb_build_object('readback_digest',v_digest);
end $fn$;

create or replace function private.lf_post_pase_waiver_consume_v1(
  p_waiver_id bigint,
  p_post_pase_execution_id text,
  p_control_id text,
  p_plan_digest text,
  p_merge_sha text,
  p_source_revision text,
  p_subject_ref text,
  p_consumer_execution_id text,
  p_request_digest text
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public,extensions
as $fn$
declare r private.lf_post_pase_waivers%rowtype; v_scope jsonb; v_pre jsonb; v_digest text;
begin
  if p_request_digest !~ '^[0-9a-f]{64}$' or nullif(btrim(p_consumer_execution_id),'') is null then raise exception 'BLOCK_WAIVER_CONSUME_IDENTITY_INVALID'; end if;
  select * into r from private.lf_post_pase_waivers where waiver_id=p_waiver_id for update;
  if not found then return jsonb_build_object('schema_version','LF_POST_PASE_WAIVER_CONSUMPTION_READBACK_V1','authority_layer','WAIVER_AUTHORITY_STORE','decision','WAIVER_MISSING','ready',false,'waiver_id',p_waiver_id); end if;
  v_scope:=jsonb_build_object('post_pase_execution_id',p_post_pase_execution_id,'control_id',p_control_id,'plan_digest',p_plan_digest,'merge_sha',p_merge_sha,'source_revision',p_source_revision,'subject_ref',p_subject_ref);
  if (r.post_pase_execution_id,r.control_id,r.plan_digest,r.merge_sha,r.source_revision,r.subject_ref) is distinct from (p_post_pase_execution_id,p_control_id,p_plan_digest,p_merge_sha,p_source_revision,p_subject_ref) then return jsonb_build_object('schema_version','LF_POST_PASE_WAIVER_CONSUMPTION_READBACK_V1','authority_layer','WAIVER_AUTHORITY_STORE','decision','WAIVER_SCOPE_MISMATCH','ready',false,'waiver_id',p_waiver_id,'scope',v_scope); end if;
  if not r.active or r.uses_count<>0 or r.max_uses<>1 or r.expires_at<=clock_timestamp() then return jsonb_build_object('schema_version','LF_POST_PASE_WAIVER_CONSUMPTION_READBACK_V1','authority_layer','WAIVER_AUTHORITY_STORE','decision','WAIVER_NOT_CONSUMABLE','ready',false,'waiver_id',p_waiver_id,'scope',v_scope,'uses_count',r.uses_count,'max_uses',r.max_uses,'active',r.active); end if;
  update private.lf_post_pase_waivers set uses_count=1,active=false,consumed_at=clock_timestamp(),consumed_by_execution_id=p_consumer_execution_id,consumed_by_request_digest=p_request_digest,updated_at=clock_timestamp() where waiver_id=p_waiver_id returning * into r;
  v_pre:=jsonb_build_object('schema_version','LF_POST_PASE_WAIVER_CONSUMPTION_READBACK_V1','authority_layer','WAIVER_AUTHORITY_STORE','decision','WAIVER_CONSUMED','ready',true,'waiver_id',r.waiver_id,'scope',v_scope,'max_uses',r.max_uses,'uses_count',r.uses_count,'active',r.active,'consumed_at',r.consumed_at,'consumed_by_execution_id',r.consumed_by_execution_id,'consumed_by_request_digest',r.consumed_by_request_digest,'grant_sha256',r.grant_sha256);
  v_digest:=encode(extensions.digest(convert_to(v_pre::text,'UTF8'),'sha256'),'hex');
  return v_pre||jsonb_build_object('readback_digest',v_digest);
end $fn$;

revoke all on table private.lf_post_pase_waivers from public,anon,authenticated;
revoke all on function private.lf_post_pase_waiver_readback_v1(bigint,text,text,text,text,text,text) from public,anon,authenticated;
revoke all on function private.lf_post_pase_waiver_consume_v1(bigint,text,text,text,text,text,text,text,text) from public,anon,authenticated;

