jsonb_build_object('solution_code','WAIVER_AUTHORITY_V1','work_code','SADM-PP-L3-018','store','private.lf_post_pase_waivers','readback_function','private.lf_post_pase_waiver_readback_v1','consume_function','private.lf_post_pase_waiver_consume_v1','validation_exemption_store_reused',false,'max_ttl_seconds',3600,'max_uses',1,'cutover_executed',true,'runtime_authorized',false,'production_authorized',false),
jsonb_build_object('schema_version','WAIVER_AUTHORITY_ASSET_METADATA_V1','entry_guard','ORCHESTRATOR_EXECUTION_GUARD_V1','decisions',jsonb_build_array('WAIVER_AUTHORIZED','WAIVER_BLOCKED'),'closure_decision_forbidden',true,'waived_output_forbidden',true,'approval_authority','LF_GOVERNANCE','required_cross_bind',jsonb_build_array('post_pase_execution_id','control_id','plan_digest','merge_sha','source_revision','subject_ref','request_digest'),'registry_cutover_state','ENFORCED'),
'8c1d2f6c-4a1c-4f80-9d3d-018000000001'::uuid,'EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001','EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001')
