insert into public.lf_activo_relaciones(codigo_activo,relacionado_codigo,relacion_tipo,valor_original,fuente,migration_batch_id,created_by_execution_id,updated_by_execution_id) values
('WAIVER_AUTHORITY','LF_GOVERNANCE','RELACIONADO_CAPACIDADES','administrative owner and approval authority','sandbox/lf_contract_gate_test/waiver_authority/waiver_authority_contract_v1.json','8c1d2f6c-4a1c-4f80-9d3d-018000000001'::uuid,'EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001','EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001'),
('WAIVER_AUTHORITY','PLAN_AUTHORITY_DRIFT_GUARD','DEPENDE_DE','plan scope and authorized delta validation','sandbox/lf_contract_gate_test/waiver_authority/waiver_authority_contract_v1.json','8c1d2f6c-4a1c-4f80-9d3d-018000000001'::uuid,'EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001','EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001'),
('WAIVER_AUTHORITY','CURRENTNESS_AUTHORITY','DEPENDE_DE','source revision currentness','sandbox/lf_contract_gate_test/waiver_authority/waiver_authority_contract_v1.json','8c1d2f6c-4a1c-4f80-9d3d-018000000001'::uuid,'EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001','EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001') on conflict do nothing;

do $$
declare v_manifest jsonb; v_sha text; v_existing text; v_promote jsonb; v_execution_id constant text:='EXEC-L5-WAIVER-AUTHORITY-CUTOVER-V1-20261001';
begin
  v_manifest:=jsonb_build_object('schema_version','LF_CAPABILITY_MANIFEST_V1','capability_code','WAIVER_AUTHORITY','version','1.0.0','contract',jsonb_build_object('input','LF_WAIVER_AUTHORITY_REQUEST_V1 + PLAN_CURRENTNESS_GRANT_CONSUMPTION_READBACKS','output','LF_WAIVER_AUTHORITY_RECEIPT_V1','authority','EXACT_APPROVED_CURRENT_ONE_USE_WAIVER_ONLY'),'delivery',jsonb_build_object('mode','SUPABASE_STORE_PLUS_VERSIONED_REPOSITORY_EVALUATOR','core','sandbox/lf_contract_gate_test/waiver_authority/waiver_authority_v1.py','store','private.lf_post_pase_waivers'),'installation',jsonb_build_object('required',false,'reinstall_required',false,'package_update_mode','DATABASE_NATIVE_CUTOVER'),'dependencies',jsonb_build_object('capabilities',jsonb_build_array('PLAN_AUTHORITY_DRIFT_GUARD','CURRENTNESS_AUTHORITY'),'governance',jsonb_build_array('LF_GOVERNANCE','ORCHESTRATOR_EXECUTION_GUARD_V1')),'compatibility',jsonb_build_object('unknown_state','FAIL_CLOSED','validation_exemption_semantic_reuse',false,'one_use',true,'max_ttl_seconds',3600,'functional_core_unchanged',true),'migration',jsonb_build_object('mode','DEDICATED_STORE_AND_REGISTRY_CUTOVER','work_code','SADM-PP-L5-022','legacy_retirement',false),'usage',jsonb_build_object('core','sandbox/lf_contract_gate_test/waiver_authority/waiver_authority_v1.py','contract','sandbox/lf_contract_gate_test/waiver_authority/waiver_authority_contract_v1.json','validator','sandbox/lf_contract_gate_test/waiver_authority/test_waiver_authority_v1.py','entrypoint','public.fn_lf_capability_bind_from_orchestrator_v1'),'currentness',jsonb_build_object('authority_ref','github://cristhianlujan/claude-persona-lf-patch@a918c85af086d08a085bab2db5f70cb6b31b62eb','source_revision_immutable',true,'core_blob_sha1','839792277cf71f2a3f3585e2e1f0b21351da533c','test_blob_sha1','397a612f044332b359f251f8d8101948be73a376','terminal_source_event_id',19624));
  v_sha:=encode(extensions.digest(convert_to(v_manifest::text,'UTF8'),'sha256'),'hex');
  insert into public.lf_capability_registry(capability_code,capability_name,capability_kind,owner_scope,status,description,created_by_execution_id,updated_by_execution_id,entry_guard_required,entry_guard_code)
  values('WAIVER_AUTHORITY','Waiver Authority','TRANSVERSAL','LF_GOVERNANCE','ACTIVE','Exact-scope approved current one-use POST-PASE waiver authority with dedicated store and anti-replay consumption.',v_execution_id,v_execution_id,true,'ORCHESTRATOR_EXECUTION_GUARD_V1') on conflict(capability_code) do update set owner_scope='LF_GOVERNANCE',status='ACTIVE',entry_guard_required=true,entry_guard_code='ORCHESTRATOR_EXECUTION_GUARD_V1',updated_at=now(),updated_by_execution_id=v_execution_id;
  select manifest_sha256 into v_existing from public.lf_capability_version_registry where capability_code='WAIVER_AUTHORITY' and version='1.0.0';
  if v_existing is not null and v_existing<>v_sha then raise exception 'WAIVER_AUTHORITY_VERSION_1_0_0_MANIFEST_CONFLICT'; end if;
  insert into public.lf_capability_version_registry(capability_code,version,version_major,version_minor,version_patch,release_state,supersedes_version,manifest,manifest_sha256,source_ref,docs_ref,validator_ref,created_by_execution_id)
  values('WAIVER_AUTHORITY','1.0.0',1,0,0,'RELEASED',null,v_manifest,v_sha,'github://cristhianlujan/claude-persona-lf-patch@a918c85af086d08a085bab2db5f70cb6b31b62eb/sandbox/lf_contract_gate_test/waiver_authority/waiver_authority_v1.py','github://cristhianlujan/claude-persona-lf-patch@a918c85af086d08a085bab2db5f70cb6b31b62eb/sandbox/lf_contract_gate_test/waiver_authority/README.md','github://cristhianlujan/claude-persona-lf-patch@a918c85af086d08a085bab2db5f70cb6b31b62eb/sandbox/lf_contract_gate_test/waiver_authority/test_waiver_authority_v1.py',v_execution_id) on conflict(capability_code,version) do nothing;
  v_promote:=public.fn_lf_capability_promote_v1('WAIVER_AUTHORITY','1.0.0',null,v_execution_id,'L5 isolated WAIVER_AUTHORITY dedicated-store cutover; validation exemptions remain semantically separate.');
  if coalesce((v_promote->>'ready')::boolean,false) is not true then raise exception 'WAIVER_AUTHORITY_CURRENT_POINTER_BLOCKED:%',v_promote::text; end if;
end $$;
